// --- working out when a schedule next comes round --------------------------
// The clock inside this agent is UTC unless somebody set GENERIC_TIMEZONE, and
// in the cloud it usually is. So "8am" has to be pinned to a named zone or a
// Melbourne morning fires at six in the evening. Every schedule carries its own
// timezone, and everything below converts between that zone's wall clock and a
// real instant.
const DAY_NAMES = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];

const zoneIsReal = (zone) => {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: zone });
    return true;
  } catch {
    return false;
  }
};

const zoneParts = (instant, zone) => {
  const read = {};
  for (const part of new Intl.DateTimeFormat('en-US', {
    timeZone: zone, hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  }).formatToParts(instant)) {
    read[part.type] = part.value;
  }
  return {
    year: Number(read.year), month: Number(read.month), day: Number(read.day),
    // Some environments render midnight as hour 24 rather than 0.
    hour: Number(read.hour) % 24, minute: Number(read.minute), second: Number(read.second),
  };
};

// How far that zone sits from UTC at that moment, daylight saving included.
const zoneOffsetMinutes = (instant, zone) => {
  const at = zoneParts(instant, zone);
  return (Date.UTC(at.year, at.month - 1, at.day, at.hour, at.minute, at.second) - instant.getTime()) / 60000;
};

// A wall-clock time in that zone, back to a real instant. The offset depends on
// the answer, so it is applied twice: once against a guess, then again against
// the offset that guess actually landed in. That second pass is what keeps the
// hour right on the two days a year the clocks move.
const instantAt = (year, month, day, hour, minute, zone) => {
  const wall = Date.UTC(year, month - 1, day, hour, minute, 0);
  const guess = new Date(wall - zoneOffsetMinutes(new Date(wall), zone) * 60000);
  return new Date(wall - zoneOffsetMinutes(guess, zone) * 60000);
};

// The first moment strictly after `after` that matches the rule, or null.
const nextRunAfter = (rule, after) => {
  const zone = rule.timezone;
  if (!zoneIsReal(zone)) return null;
  const clock = String(rule.timeOfDay ?? '').split(':').map(Number);
  const hour = clock[0];
  const minute = clock[1];
  if (!Number.isInteger(hour) || !Number.isInteger(minute)) return null;

  if (rule.frequency === 'once') {
    if (rule.onDate) {
      const parts = String(rule.onDate).split('-').map(Number);
      const once = instantAt(parts[0], parts[1], parts[2], hour, minute, zone);
      return once.getTime() > after.getTime() ? once : null;
    }
  }

  const from = zoneParts(after, zone);
  for (let step = 0; step <= 400; step += 1) {
    // Adding to the day number rolls months and years over on its own.
    const day = new Date(Date.UTC(from.year, from.month - 1, from.day + step));
    const year = day.getUTCFullYear();
    const month = day.getUTCMonth() + 1;
    const date = day.getUTCDate();
    const weekday = DAY_NAMES[day.getUTCDay()];
    if (rule.frequency === 'weekdays' && (weekday === 'saturday' || weekday === 'sunday')) continue;
    if (rule.frequency === 'weekly' && weekday !== rule.dayOfWeek) continue;
    if (rule.frequency === 'monthly' && date !== Number(rule.dayOfMonth)) continue;
    const candidate = instantAt(year, month, date, hour, minute, zone);
    if (candidate.getTime() > after.getTime()) return candidate;
  }
  return null;
};

// What the agent reads back to the owner, in their own timezone.
const inWords = (instant, zone) => {
  if (!instant || !zoneIsReal(zone)) return '';
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: zone, weekday: 'short', day: 'numeric', month: 'short',
    year: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true,
  }).format(instant) + ' (' + zone + ')';
};

const clockInWords = (timeOfDay) => {
  const clock = String(timeOfDay ?? '').split(':').map(Number);
  const hour = clock[0];
  const minute = clock[1];
  if (!Number.isInteger(hour) || !Number.isInteger(minute)) return String(timeOfDay ?? '');
  const suffix = hour < 12 ? 'am' : 'pm';
  const shown = hour % 12 === 0 ? 12 : hour % 12;
  return shown + ':' + String(minute).padStart(2, '0') + ' ' + suffix;
};

const patternInWords = (rule) => {
  const at = 'at ' + clockInWords(rule.timeOfDay);
  if (rule.frequency === 'daily') return 'every day ' + at;
  if (rule.frequency === 'weekdays') return 'every weekday ' + at;
  if (rule.frequency === 'weekly') {
    const day = String(rule.dayOfWeek ?? '');
    return 'every ' + day.charAt(0).toUpperCase() + day.slice(1) + ' ' + at;
  }
  if (rule.frequency === 'monthly') return 'on day ' + rule.dayOfMonth + ' of each month ' + at;
  return 'once, ' + at;
};


const input = $('Tool Input').first().json;
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && typeof row.scheduleId === 'string' && row.scheduleId !== '');

const text = (value, limit) => {
  const raw = typeof value === 'string' ? value.trim() : '';
  return raw.slice(0, limit ?? 200);
};
const normalise = (value) => String(value).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const sessionId = text(input.sessionId, 60);
const requestId = text(input.requestId, 60);
const proposedInput = {
  sessionId,
  requestId,
  scheduleId: text(input.scheduleId, 40),
  name: text(input.name, 80),
  action: text(input.action, 20),
};
const fail = (code, message) => ({ json: {
  valid: false, sessionId, requestId, proposedInput,
  response: { ok: false, error: { code, message } },
} });

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) {
  return [fail('INVALID_SESSION', 'Changing a schedule needs a valid conversation and request ID.')];
}

const ACTIONS = {
  pause: 'pause', paused: 'pause', off: 'pause', stop: 'pause', disable: 'pause',
  hold: 'pause', suspend: 'pause', snooze: 'pause',
  resume: 'resume', on: 'resume', start: 'resume', enable: 'resume',
  unpause: 'resume', restart: 'resume',
  delete: 'delete', remove: 'delete', cancel: 'delete', drop: 'delete', 'delete-it': 'delete',
};
const action = ACTIONS[proposedInput.action.toLowerCase().replace(/[\s_]+/g, '-')]
  ?? ACTIONS[proposedInput.action.toLowerCase().replace(/[\s_-]+/g, '')];
if (!action) {
  return [fail('ACTION_REQUIRED', 'Say what to do with the schedule: pause to stop it running for now, resume to start it again, or delete to remove it for good. Ask the user which they mean rather than choosing for them, because delete cannot be undone.')];
}

if (rows.length === 0) {
  return [fail('NOTHING_SCHEDULED', 'There are no schedules saved, so there is nothing to change.')];
}

let row = null;
if (proposedInput.scheduleId !== '') {
  row = rows.find((entry) => entry.scheduleId === proposedInput.scheduleId) ?? null;
}
if (!row && proposedInput.name !== '') {
  const asked = normalise(proposedInput.name);
  row = rows.find((entry) => normalise(entry.name ?? '') === asked)
    ?? rows.find((entry) => normalise(entry.name ?? '').includes(asked))
    ?? null;
}
if (!row) {
  const known = rows.map((entry) => entry.scheduleId + ' (' + String(entry.name ?? '') + ')').join(', ');
  return [fail('SCHEDULE_NOT_FOUND', 'No saved schedule matches that. These exist: ' + known + '. Read them back to the user and ask which one they mean, then call this again with that scheduleId.')];
}

const rule = {
  frequency: row.frequency, timeOfDay: row.timeOfDay, dayOfWeek: row.dayOfWeek,
  dayOfMonth: row.dayOfMonth, onDate: row.onDate, timezone: row.timezone,
};
const runsWhen = patternInWords(rule);

// Resuming works out the next run from now, so a schedule paused for a
// fortnight does not fire the moment it is switched back on.
let nextRunAt = '';
let nextRun = '';
if (action === 'resume') {
  const next = nextRunAfter(rule, new Date());
  if (next === null) {
    return [fail('CANNOT_RESUME', 'This was a one-off and its time has already gone by, so there is nothing left to resume. Offer to create a new schedule instead.')];
  }
  nextRunAt = next.toISOString();
  nextRun = inWords(next, row.timezone);
}

return [{ json: {
  valid: true,
  sessionId,
  requestId,
  proposedInput,
  deleting: action === 'delete',
  action,
  scheduleId: row.scheduleId,
  name: String(row.name ?? ''),
  agentId: String(row.agentId ?? ''),
  runsWhen,
  timezone: String(row.timezone ?? ''),
  enabled: action === 'resume' ? 'yes' : 'no',
  nextRunAt,
  nextRun,
} }];

const plan = $('Validate Change').first().json;
const changed = $json.id !== undefined || $json.scheduleId === plan.scheduleId;

if (!changed) {
  return [{ json: { ...plan, response: { ok: false, error: {
    code: 'CHANGE_FAILED',
    message: 'The schedule could not be changed. Nothing was altered. Say so plainly rather than reporting it as done.',
  } } } }];
}

const done = {
  pause: 'Paused. It stays saved and will not run until the user asks for it back.',
  resume: 'Switched back on.',
  delete: 'Deleted. It is gone for good; a new one would have to be created from scratch.',
}[plan.action];

return [{ json: { ...plan, response: {
  ok: true,
  action: plan.action,
  schedule: {
    scheduleId: plan.scheduleId,
    name: plan.name,
    agent: plan.agentId,
    runsWhen: plan.runsWhen,
    timezone: plan.timezone,
    status: plan.action === 'delete' ? 'deleted' : (plan.action === 'resume' ? 'on' : 'paused'),
    nextRun: plan.nextRun,
  },
  message: done + ' Name the schedule back to the user so they know which one changed'
    + (plan.action === 'resume' ? ', and tell them when it next runs.' : '.'),
} } }];

const input = $('Validate Change').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'update_schedule',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').first().json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
